import{_ as s,o as r,c as t,a2 as i}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse(`{"title":"Mécanisme d'ouverture des ressources de culture","description":"","frontmatter":{},"headers":[],"relativePath":"fr/18-修炼资源开放机制.md","filePath":"fr/18-修炼资源开放机制.md","lastUpdated":1789183869000}`),a={name:"fr/18-修炼资源开放机制.md"};function n(o,e,u,l,d,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="mecanisme-d-ouverture-des-ressources-de-culture" tabindex="-1">Mécanisme d&#39;ouverture des ressources de culture <a class="header-anchor" href="#mecanisme-d-ouverture-des-ressources-de-culture" aria-label="Permalink to &quot;Mécanisme d&#39;ouverture des ressources de culture&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>18</td></tr><tr><td>Module</td><td>Lois cosmiques et systèmes de culture</td></tr><tr><td>Mots-clés</td><td>Ouverture des ressources, Ressources de culture, Mécanisme de répartition, Antimonopole, Équité des ressources</td></tr></tbody></table><h2 id="i-contexte-et-signification-du-mecanisme-d-ouverture-des-ressources-de-culture" tabindex="-1">I. Contexte et signification du mécanisme d&#39;ouverture des ressources de culture <a class="header-anchor" href="#i-contexte-et-signification-du-mecanisme-d-ouverture-des-ressources-de-culture" aria-label="Permalink to &quot;I. Contexte et signification du mécanisme d&#39;ouverture des ressources de culture&quot;">​</a></h2><p>À l&#39;ère du prédationisme, les ressources de culture étaient l&#39;objet de convoitise le plus central. Des ressources telles que les veines spirituelles, les champs de médicaments, les veines de minerai d&#39;énergie, les trésors du ciel et de la terre et les royaumes secrets de culture étaient monopolisées par quelques experts et sectes, et les masses du bas de l&#39;échelle ne pouvaient presque pas obtenir de ressources de culture régulières. Ce monopole des ressources a non seulement provoqué une grave solidification des classes, mais a aussi conduit à d&#39;innombrables guerres et massacres causés par la convoitise des ressources. Le monopole des ressources est le fondement économique du système prédationniste — tant que les ressources sont monopolisées par quelques-uns, « Un Chemin pour Chacun » ne peut être qu&#39;une phrase vide.</p><p>Après l&#39;établissement de la Civilisation Symbiotique de l&#39;Ancre, l&#39;« ouverture des ressources de culture » a été faite l&#39;une des réformes institutionnelles les plus centrales. L&#39;objectif central du mécanisme d&#39;ouverture des ressources de culture est : briser le monopole des ressources, garantir que chaque vie peut obtenir des ressources de culture de base, tout en incitant à l&#39;utilisation efficace et à la création continue des ressources par le mécanisme de répartition À Chacun Selon son Travail. L&#39;ouverture des ressources n&#39;est pas une « répartition égale des ressources », mais un « accès équitable aux ressources » — sur la prémiisse de garantir les besoins fondamentaux, la répartition des ressources est liée à la contribution individuelle, tandis que toute forme de monopole des ressources est strictement interdite.</p><p>La signification du mécanisme d&#39;ouverture des ressources de culture réside dans le fait qu&#39;il déracine le terreau du prédationisme du fondement économique, fournit des garanties matérielles pour la vulgarisation réelle des Trois Cents Systèmes de Culture, fournit un soutien de ressources à l&#39;objectif social d&#39;« Un Chemin pour Chacun » et crée un point de départ équitable pour la progression commune des Dix Mille Races.</p><h2 id="ii-classification-et-classement-des-ressources-de-culture" tabindex="-1">II. Classification et classement des ressources de culture <a class="header-anchor" href="#ii-classification-et-classement-des-ressources-de-culture" aria-label="Permalink to &quot;II. Classification et classement des ressources de culture&quot;">​</a></h2><h3 id="_2-1-classification-des-ressources" tabindex="-1">2.1 Classification des ressources <a class="header-anchor" href="#_2-1-classification-des-ressources" aria-label="Permalink to &quot;2.1 Classification des ressources&quot;">​</a></h3><p>Les ressources de culture dans Heng Yuan Zhou sont divisées en catégories majeures selon leur nature et leur usage :</p><table tabindex="0"><thead><tr><th>Catégorie de ressources</th><th>Contenu spécifique</th><th>Usages principaux</th></tr></thead><tbody><tr><td>Ressources énergétiques</td><td>Veines spirituelles, veines de minerai d&#39;énergie, cristaux de qi spirituel, fragments d&#39;énergie de l&#39;Origine, etc.</td><td>Fournir l&#39;apport énergétique nécessaire à la culture</td></tr><tr><td>Ressources médicamenteuses</td><td>Médicaments spirituels, herbes immortelles, matériaux d&#39;alchimie, pilules finies, etc.</td><td>Assister la culture, traiter les blessures et maladies, franchir les goulots d&#39;étranglement</td></tr><tr><td>Ressources d&#39;équipement</td><td>Artefacts de culture, instruments de lois, dispositifs de multiplication, équipements spatiaux, etc.</td><td>Améliorer l&#39;efficacité de la culture, assister la manipulation des lois</td></tr><tr><td>Ressources spatiales</td><td>Royaumes secrets de culture, zones de concentration de qi spirituel, salles de compréhension des lois, Espace d&#39;Isolement, etc.</td><td>Fournir des environnements de culture spéciaux</td></tr><tr><td>Ressources de connaissances</td><td>Techniques de culture, compréhensions de culture, matériaux de recherche sur les lois, documents techniques, etc.</td><td>Fournir des conseils théoriques et méthodologiques pour la culture</td></tr><tr><td>Ressources biologiques</td><td>Bêtes spirituelles, plantes spirituelles, vies liées par contrat, symbiotes, etc.</td><td>Fournir une assistance à la culture, une circulation symbiotique, des capacités spéciales</td></tr><tr><td>Ressources de plans</td><td>Plans non développés, droits d&#39;utilisation des canaux entre plans, fragments de noyaux de plans, etc.</td><td>Fournir des espaces de culture et de développement à grande échelle</td></tr></tbody></table><h3 id="_2-2-classement-des-ressources" tabindex="-1">2.2 Classement des ressources <a class="header-anchor" href="#_2-2-classement-des-ressources" aria-label="Permalink to &quot;2.2 Classement des ressources&quot;">​</a></h3><p>Toutes les ressources de culture sont divisées en cinq grades selon leur rareté et leur valeur :</p><table tabindex="0"><thead><tr><th>Grade</th><th>Nom</th><th>Rareté</th><th>Mode de répartition</th></tr></thead><tbody><tr><td>Premier</td><td>Ressources ordinaires</td><td>Large distribution, réserves abondantes</td><td>Ouverture gratuite ou répartition à bas prix</td></tr><tr><td>Deuxième</td><td>Ressources fines</td><td>Assez courantes, réserves modérées</td><td>Répartition de base + échange par contribution</td></tr><tr><td>Troisième</td><td>Ressources rares</td><td>Assez rares, réserves limitées</td><td>Échange par contribution + approbation par demande</td></tr><tr><td>Quatrième</td><td>Ressources épiques</td><td>Très rares, réserves extrêmement faibles</td><td>Répartition concurrentielle + priorité aux projets de niveau civilisation</td></tr><tr><td>Cinquième</td><td>Ressources légendaires</td><td>Extrêmement rares, presque disparues</td><td>Répartition spéciale par l&#39;organe de décision le plus élevé de la civilisation</td></tr></tbody></table><h2 id="iii-principes-fondamentaux-de-l-ouverture-des-ressources" tabindex="-1">III. Principes fondamentaux de l&#39;ouverture des ressources <a class="header-anchor" href="#iii-principes-fondamentaux-de-l-ouverture-des-ressources" aria-label="Permalink to &quot;III. Principes fondamentaux de l&#39;ouverture des ressources&quot;">​</a></h2><h3 id="_3-1-principe-de-garantie-fondamentale" tabindex="-1">3.1 Principe de garantie fondamentale <a class="header-anchor" href="#_3-1-principe-de-garantie-fondamentale" aria-label="Permalink to &quot;3.1 Principe de garantie fondamentale&quot;">​</a></h3><p>Chaque vie a le droit d&#39;obtenir les ressources de premier et deuxième grade nécessaires au maintien de la culture de base. Les ressources de garantie fondamentale sont réparties gratuitement ou à bas prix par le « système de sécurité Un Chemin pour Chacun », sans seuils ni discrimination. Le niveau de garantie fondamentale est périodiquement ajusté par le Parlement de la République des Dix Mille Races selon les conditions de ressources et le stade de développement de la civilisation, assurant que le niveau de garantie correspond à la capacité de charge de la civilisation.</p><h3 id="_3-2-principe-a-chacun-selon-son-travail" tabindex="-1">3.2 Principe À Chacun Selon son Travail <a class="header-anchor" href="#_3-2-principe-a-chacun-selon-son-travail" aria-label="Permalink to &quot;3.2 Principe À Chacun Selon son Travail&quot;">​</a></h3><p>Au-dessus de la garantie fondamentale, la répartition des ressources de troisième grade et au-dessus se base principalement sur la valeur de contribution individuelle au réseau symbiotique. Plus la contribution est grande, plus les ressources échangeables sont nombreuses et plus le grade est élevé. Le principe À Chacun Selon son Travail incite les cultivateurs à élever diligemment leurs niveaux et à apporter de plus grandes contributions à la civilisation, tout en assurant que les ressources affluent vers les individus et groupes qui peuvent les utiliser le plus efficacement.</p><h3 id="_3-3-principe-antimonopole" tabindex="-1">3.3 Principe antimonopole <a class="header-anchor" href="#_3-3-principe-antimonopole" aria-label="Permalink to &quot;3.3 Principe antimonopole&quot;">​</a></h3><p>Tout individu, organisation ou race est strictement interdit de monopoliser les ressources de culture. Les mesures antimonopoles spécifiques comprennent :</p><ul><li>Les ressources de troisième grade et au-dessus détenues par un seul individu ou organisation ne doivent pas dépasser 1% des réserves totales de la civilisation</li><li>L&#39;accaparement est interdit — les détenteurs de ressources ne doivent pas accaparer malveillamment les ressources ni gonfler les prix en période de pénurie</li><li>La possession exclusive est interdite — les ressources publiques (telles que les veines spirituelles publiques, les royaumes secrets publics, etc.) ne doivent pas être possédées exclusivement par des parties privées</li><li>Les violations de la loi antimonopole seront sévèrement sanctionnées par le Tribunal des Ancres, notamment par la confiscation des ressources, la mise à zéro des valeurs de contribution, la restriction des permissions de culture, etc.</li></ul><h3 id="_3-4-principe-d-utilisation-durable" tabindex="-1">3.4 Principe d&#39;utilisation durable <a class="header-anchor" href="#_3-4-principe-d-utilisation-durable" aria-label="Permalink to &quot;3.4 Principe d&#39;utilisation durable&quot;">​</a></h3><p>Le développement et l&#39;utilisation de toutes les ressources doivent suivre le principe de durabilité, et l&#39;exploitation prédatrice du type « vider l&#39;étang pour attraper le poisson » est interdite. Les exigences spécifiques comprennent :</p><ul><li>La vitesse de développement des ressources ne doit pas dépasser la vitesse de régénération naturelle de la ressource (pour les ressources non renouvelables, des plans alternatifs doivent être formulés)</li><li>Le développement des ressources doit subir une évaluation d&#39;impact environnemental, empêchant les dommages irréversibles à l&#39;environnement écologique</li><li>Pour les ressources menacées, des politiques d&#39;interdiction ou de restriction d&#39;exploitation sont mises en œuvre, protégeant la capacité de régénération des ressources</li><li>Encourager la culture artificielle et la synthèse de ressources rares par des moyens technologiques (tels que l&#39;ingénierie des lois, la technologie de multiplication, etc.), réduisant la dépendance aux ressources naturelles</li></ul><h3 id="_3-5-principe-d-ouverture-et-de-transparence" tabindex="-1">3.5 Principe d&#39;ouverture et de transparence <a class="header-anchor" href="#_3-5-principe-d-ouverture-et-de-transparence" aria-label="Permalink to &quot;3.5 Principe d&#39;ouverture et de transparence&quot;">​</a></h3><p>Le processus de répartition des ressources doit être ouvert et transparent, soumis à la supervision de toutes les vies :</p><ul><li>Les réserves, la distribution et le statut de développement de toutes les ressources publiques sont régulièrement divulgués à la société</li><li>Les normes, les processus et les résultats de la répartition des ressources sont ouverts et vérifiables</li><li>Un mécanisme d&#39;appel de la répartition des ressources est établi ; les individus qui s&#39;opposent aux résultats de répartition peuvent demander un réexamen</li><li>Le « Comité d&#39;équité des ressources » relevant du Tribunal des Ancres est établi pour superviser spécifiquement l&#39;équité et la légalité de la répartition des ressources</li></ul><h2 id="iv-mecanismes-specifiques-de-l-ouverture-des-ressources" tabindex="-1">IV. Mécanismes spécifiques de l&#39;ouverture des ressources <a class="header-anchor" href="#iv-mecanismes-specifiques-de-l-ouverture-des-ressources" aria-label="Permalink to &quot;IV. Mécanismes spécifiques de l&#39;ouverture des ressources&quot;">​</a></h2><h3 id="_4-1-mecanisme-de-contrat-lie-a-la-production" tabindex="-1">4.1 Mécanisme de contrat lié à la production <a class="header-anchor" href="#_4-1-mecanisme-de-contrat-lie-a-la-production" aria-label="Permalink to &quot;4.1 Mécanisme de contrat lié à la production&quot;">​</a></h3><p>Le contrat lié à la production est la conception institutionnelle centrale de l&#39;ouverture des ressources de culture ; son fonctionnement de base a été détaillé dans le document « Principes de répartition À Chacun Selon son Travail ». Dans le domaine de l&#39;ouverture des ressources, les applications spécifiques du contrat lié à la production comprennent :</p><ul><li><strong>Contrat de veines spirituelles</strong> : les veines spirituelles publiques sont contractées à des groupes de cultivateurs ou des communautés raciales ; les contractants sont responsables de la maintenance et du développement durable des veines spirituelles, obtenant une certaine proportion de la production des veines</li><li><strong>Contrat de champs de médicaments</strong> : les champs de médicaments publics sont contractés à des cultivateurs ayant la capacité de plantation ; les contractants sont responsables de la plantation et des soins des médicaments spirituels, avec la récolte répartie proportionnellement</li><li><strong>Gestion des royaumes secrets</strong> : les royaumes secrets publics de culture sont confiés à des équipes professionnelles pour la gestion ; les gestionnaires sont responsables de la maintenance et de la sécurité des royaumes secrets, et les utilisateurs paient des frais d&#39;utilisation raisonnables</li><li><strong>Exploration des ressources</strong> : les cultivateurs sont encouragés à participer à l&#39;exploration des ressources des zones non développées ; les explorateurs ont des droits de contrat prioritaires sur les nouvelles ressources découvertes</li></ul><h3 id="_4-2-mecanisme-d-echange-par-valeur-de-contribution" tabindex="-1">4.2 Mécanisme d&#39;échange par valeur de contribution <a class="header-anchor" href="#_4-2-mecanisme-d-echange-par-valeur-de-contribution" aria-label="Permalink to &quot;4.2 Mécanisme d&#39;échange par valeur de contribution&quot;">​</a></h3><p>La civilisation symbiotique a établi un « système d&#39;échange par valeur de contribution » unifié ; les cultivateurs peuvent accumuler des valeurs de contribution en contribuant au réseau symbiotique, puis échanger les valeurs de contribution contre diverses ressources de culture :</p><ul><li>Les moyens d&#39;obtenir des valeurs de contribution comprennent : les progrès de culture, le partage de connaissances, l&#39;innovation technologique, le service public, la restauration écologique, la garde de la civilisation, etc.</li><li>Le système d&#39;échange met en œuvre des « prix clairement marqués » ; chaque ressource a un prix clair en valeurs de contribution, et le prix est dynamiquement ajusté selon la rareté et la demande de la ressource</li><li>Le système d&#39;échange soutient la fonction d&#39;« avance » — les cultivateurs prometteurs peuvent avancer un certain montant de valeurs de contribution pour l&#39;échange de ressources, remboursant à l&#39;avenir en apportant des contributions</li><li>Le système d&#39;échange est connecté en temps réel au réseau d&#39;ancres, assurant la sécurité et la fiabilité de l&#39;enregistrement et de l&#39;échange des valeurs de contribution</li></ul><h3 id="_4-3-mecanisme-d-ouverture-gratuite-des-ressources-publiques" tabindex="-1">4.3 Mécanisme d&#39;ouverture gratuite des ressources publiques <a class="header-anchor" href="#_4-3-mecanisme-d-ouverture-gratuite-des-ressources-publiques" aria-label="Permalink to &quot;4.3 Mécanisme d&#39;ouverture gratuite des ressources publiques&quot;">​</a></h3><p>Les types de ressources suivants sont librement ouverts à toutes les vies :</p><ul><li><strong>Ressources de connaissances</strong> : les techniques de base des Trois Cents Systèmes de Culture, les compréhensions de culture publiques, les matériaux de recherche sur les lois fondamentales, etc.</li><li><strong>Ressources énergétiques de premier grade</strong> : qi spirituel de base, cristaux d&#39;énergie ordinaires et autres ressources énergétiques de bas ordre largement distribuées</li><li><strong>Espaces publics de culture</strong> : salles de culture publiques, salles de compréhension des lois fondamentales, Espace d&#39;Isolement ordinaire, etc.</li><li><strong>Ressources médicales de base</strong> : techniques de guérison de base, pilules ordinaires de cicatrisation, services de réadaptation de base, etc.</li><li><strong>Ressources éducatives de base</strong> : cours de culture de base, guidance des mentors d&#39;introduction, utilisation d&#39;équipements de culture généraux, etc.</li></ul><h3 id="_4-4-mecanisme-de-repartition-ciblee-des-ressources-speciales" tabindex="-1">4.4 Mécanisme de répartition ciblée des ressources spéciales <a class="header-anchor" href="#_4-4-mecanisme-de-repartition-ciblee-des-ressources-speciales" aria-label="Permalink to &quot;4.4 Mécanisme de répartition ciblée des ressources spéciales&quot;">​</a></h3><p>Pour les ressources rares de quatrième et cinquième grade, un mécanisme de « répartition ciblée » est mis en œuvre :</p><ul><li>Les ressources rares sont prioritairement affectées aux projets clés de niveau civilisation (tels que la construction d&#39;ancres, le développement des plans, les percées technologiques, etc.)</li><li>Pour les individus ayant des besoins spéciaux (tels que le besoin de ressources spécifiques pour franchir des niveaux clés, le besoin de médicaments rares pour traiter des blessures et maladies spéciales, etc.), une répartition ciblée peut être obtenue par demande et approbation</li><li>Les plans de répartition des ressources rares sont formulés par le « Comité de répartition des ressources » relevant du Parlement de la République des Dix Mille Races, et exécutés après approbation du Parlement</li><li>Les résultats de la répartition ciblée sont divulgués à la société et soumis à la supervision</li></ul><h2 id="v-creation-de-ressources-et-developpement-durable" tabindex="-1">V. Création de ressources et développement durable <a class="header-anchor" href="#v-creation-de-ressources-et-developpement-durable" aria-label="Permalink to &quot;V. Création de ressources et développement durable&quot;">​</a></h2><p>L&#39;ouverture des ressources de culture n&#39;est pas seulement « répartir le stock existant », mais aussi « créer un volume incrémental ». La civilisation symbiotique encourage vigoureusement la création artificielle et le développement durable des ressources :</p><h3 id="_5-1-culture-artificielle-des-ressources" tabindex="-1">5.1 Culture artificielle des ressources <a class="header-anchor" href="#_5-1-culture-artificielle-des-ressources" aria-label="Permalink to &quot;5.1 Culture artificielle des ressources&quot;">​</a></h3><ul><li><strong>Plantation artificielle des médicaments spirituels</strong> : par la technologie d&#39;ingénierie des lois, cultiver divers médicaments spirituels dans des environnements artificiels, réduisant la dépendance aux médicaments spirituels sauvages</li><li><strong>Production artificielle d&#39;énergie</strong> : par des technologies telles que les dispositifs de transformation d&#39;énergie matérielle et les générateurs de résonance des lois, produire artificiellement du qi spirituel et des cristaux d&#39;énergie</li><li><strong>Élevage artificiel des bêtes spirituelles</strong> : établir des bases d&#39;élevage de bêtes spirituelles, élever artificiellement diverses bêtes spirituelles, protégeant les populations sauvages</li><li><strong>Construction artificielle de royaumes secrets</strong> : par la technologie de la loi spatiale, construire artificiellement des royaumes secrets de culture, augmentant l&#39;offre d&#39;espaces de culture</li></ul><h3 id="_5-2-recyclage-des-ressources" tabindex="-1">5.2 Recyclage des ressources <a class="header-anchor" href="#_5-2-recyclage-des-ressources" aria-label="Permalink to &quot;5.2 Recyclage des ressources&quot;">​</a></h3><ul><li><strong>Récupération d&#39;énergie</strong> : établir des systèmes de récupération d&#39;énergie pour récupérer et réutiliser l&#39;énergie perdue pendant la culture, l&#39;énergie dispersée en combat, etc.</li><li><strong>Traitement des résidus de médicaments</strong> : effectuer une extraction et un traitement secondaires des résidus d&#39;alchimie, améliorant le taux d&#39;utilisation des ressources médicamenteuses</li><li><strong>Recyclage et refabrication d&#39;équipements</strong> : recycler et refabriquer les équipements de culture hors d&#39;usage, réduisant le gaspillage de matériaux</li><li><strong>Usage cyclique des espaces</strong> : nettoyer et réutiliser l&#39;Espace d&#39;Isolement utilisé, les espaces de culture temporaires, etc.</li></ul><h3 id="_5-3-technologie-de-substitution-des-ressources" tabindex="-1">5.3 Technologie de substitution des ressources <a class="header-anchor" href="#_5-3-technologie-de-substitution-des-ressources" aria-label="Permalink to &quot;5.3 Technologie de substitution des ressources&quot;">​</a></h3><ul><li>Encourager le développement de substituts des ressources rares, réalisant « remplacer les matériaux rares par des matériaux communs » par des moyens technologiques</li><li>Pour les ressources légendaires non renouvelables, formuler des plans stricts de protection et d&#39;utilisation, tout en augmentant l&#39;investissement en R&amp;D de la technologie de substitution</li><li>Établir un « fonds de R&amp;D de la technologie de substitution des ressources » pour financer les projets de recherche connexes</li></ul><h2 id="vi-supervision-et-secours-de-l-ouverture-des-ressources" tabindex="-1">VI. Supervision et secours de l&#39;ouverture des ressources <a class="header-anchor" href="#vi-supervision-et-secours-de-l-ouverture-des-ressources" aria-label="Permalink to &quot;VI. Supervision et secours de l&#39;ouverture des ressources&quot;">​</a></h2><h3 id="_6-1-mecanismes-de-supervision" tabindex="-1">6.1 Mécanismes de supervision <a class="header-anchor" href="#_6-1-mecanismes-de-supervision" aria-label="Permalink to &quot;6.1 Mécanismes de supervision&quot;">​</a></h3><ul><li><strong>Surveillance en temps réel par le réseau d&#39;ancres</strong> : le réseau d&#39;ancres surveille en temps réel le développement, la répartition et l&#39;utilisation de toutes les ressources publiques, fournissant des alertes rapides en cas d&#39;anomalies</li><li><strong>Comité d&#39;équité des ressources</strong> : supervise spécifiquement l&#39;équité et la légalité de la répartition des ressources, acceptant les signalements et les plaintes</li><li><strong>Supervision sociale</strong> : toutes les vies sont encouragées à superviser et signaler les comportements inappropriés dans le développement et la répartition des ressources</li><li><strong>Audit régulier</strong> : des audits indépendants des institutions de gestion des ressources sont menés chaque année, avec les résultats divulgués à la société</li></ul><h3 id="_6-2-mecanismes-de-secours" tabindex="-1">6.2 Mécanismes de secours <a class="header-anchor" href="#_6-2-mecanismes-de-secours" aria-label="Permalink to &quot;6.2 Mécanismes de secours&quot;">​</a></h3><ul><li><strong>Appel de répartition</strong> : les individus qui s&#39;opposent aux résultats de répartition des ressources peuvent demander un réexamen au Comité d&#39;équité des ressources</li><li><strong>Arbitrage des litiges de ressources</strong> : les litiges de ressources sont arbitrés par le Tribunal des Ancres, et les résultats d&#39;arbitrage ont un effet juridique</li><li><strong>Indemnisation pour atteinte</strong> : les individus lésés par le monopole des ressources, le pillage des ressources et d&#39;autres comportements peuvent intenter des actions devant le Tribunal des Ancres pour demander une indemnisation</li><li><strong>Secours d&#39;urgence</strong> : dans des situations spéciales (telles que les catastrophes, les guerres, etc.), activer le mécanisme de répartition des ressources d&#39;urgence, assurant les besoins fondamentaux en ressources des groupes touchés</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le mécanisme d&#39;ouverture des ressources de culture est le cœur du système économique de la Civilisation Symbiotique de l&#39;Ancre. Par les cinq principes de « garantie fondamentale + À Chacun Selon son Travail + antimonopole + durabilité + ouverture et transparence », il construit un système de répartition des ressources équitable, efficace et durable. L&#39;objectif ultime du mécanisme d&#39;ouverture des ressources n&#39;est pas de laisser toutes les vies obtenir la même quantité de ressources, mais de laisser chaque vie avoir une opportunité équitable d&#39;obtenir des ressources, de laisser les ressources affluer vers les lieux où elles peuvent créer le plus de valeur, et de laisser les ressources totales de la civilisation croître continuellement dans des conditions durables. Lorsque les ressources de culture ne sont plus une propriété privée monopolisée par quelques-uns, mais une richesse publique partagée par les Dix Mille Races, amplifiée par la circulation, l&#39;idéal d&#39;« Un Chemin pour Chacun » pourra véritablement prendre racine, et l&#39;objectif de la progression commune des Dix Mille Races pourra véritablement se réaliser.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (Principes de répartition À Chacun Selon son Travail)</li><li>08-人人有路保障体系 (Système de sécurité Un Chemin pour Chacun)</li><li>22-资源分配联产承包机制 (Mécanisme de contrat lié à la production pour la répartition des ressources)</li></ul>',57)])])}const v=s(a,[["render",n]]);export{m as __pageData,v as default};
